// FROZEN (023 T164, FR-023, analysis H1). Do not edit this file.
//
// Every stored fingerprint and tombstone depends on this exact output. A
// change here would make decided messages resurface after an app update
// (SC-006, SC-014). Changing the normalization needs a new prefix (`fp2|`)
// and a migration that matches both versions; that is out of scope for v1.
//
// Its only behavioral import is `NumeralParser`. The second import is the
// domain port it implements, an abstract interface with no imports and no
// behavior. No parser file, no `SmsTextNormalizer`, no profile. Guarded by
// test/features/sms_import/data/parsing/fingerprint_golden_test.dart.
import '../../../../core/money/numeral_parser.dart';
import '../../domain/services/fingerprint_normalizer.dart';

/// The frozen v1 fingerprint normalization of a message body
/// (parser-contract §3).
///
/// A fixed copy of pipeline steps 1-3 only:
/// 1. remove bidi controls (U+200E, U+200F, U+061C, U+202A-202E,
///    U+2066-2069) and zero-width characters (U+200B-200D, U+FEFF);
/// 2. collapse every whitespace run to one space and trim;
/// 3. Western digits through `NumeralParser.toWesternDigits`.
///
/// No letter folding and no lower-casing. Sender and received time are
/// never inputs.
final class FingerprintNormalizerV1 implements FingerprintNormalizer {
  const FingerprintNormalizerV1();

  /// The version this file implements; the hash prefix is `fp1|`.
  static const int version = 1;

  @override
  String normalize(String body) {
    final buffer = StringBuffer();
    var pendingSpace = false;
    for (var i = 0; i < body.length; i++) {
      final unit = body.codeUnitAt(i);
      if (_isInvisibleMark(unit)) continue;
      if (_isWhitespace(unit)) {
        pendingSpace = buffer.isNotEmpty;
        continue;
      }
      if (pendingSpace) {
        buffer.writeCharCode(0x20);
        pendingSpace = false;
      }
      buffer.writeCharCode(unit);
    }
    return NumeralParser.toWesternDigits(buffer.toString());
  }

  static bool _isInvisibleMark(int unit) =>
      unit == 0x200E ||
      unit == 0x200F ||
      unit == 0x061C ||
      (unit >= 0x202A && unit <= 0x202E) ||
      (unit >= 0x2066 && unit <= 0x2069) ||
      (unit >= 0x200B && unit <= 0x200D) ||
      unit == 0xFEFF;

  static bool _isWhitespace(int unit) =>
      (unit >= 0x09 && unit <= 0x0D) ||
      unit == 0x20 ||
      unit == 0x85 ||
      unit == 0xA0 ||
      unit == 0x1680 ||
      (unit >= 0x2000 && unit <= 0x200A) ||
      unit == 0x2028 ||
      unit == 0x2029 ||
      unit == 0x202F ||
      unit == 0x205F ||
      unit == 0x3000;
}
